_SVG_TEMPLATE = (
    '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" '
    'fill="none" stroke="{color}" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">'
    "{body}</svg>"
)

_cache = {}


def get_pixmap(name: str, color: str, size: int = 16, ratio: float = 2.0) -> QPixmap:
    """A crisp (high-DPI) pixmap of a Lucide icon tinted with `color`."""
    key = (name, color, size, ratio)
    cached = _cache.get(key)
    if cached is not None:
        return cached

    body = _ICON_BODY.get(name)
    if body is None:
        raise KeyError(f"Unknown lucide icon: {name!r}")

    svg = _SVG_TEMPLATE.format(color=color, body=body)
    renderer = QSvgRenderer(QByteArray(svg.encode("utf-8")))
    px = int(size * ratio)
    pixmap = QPixmap(px, px)
    pixmap.fill(Qt.transparent)
    painter = QPainter(pixmap)
    painter.setRenderHint(QPainter.Antialiasing)
    renderer.render(painter)
    painter.end()
    pixmap.setDevicePixelRatio(ratio)
    _cache[key] = pixmap
    return pixmap


def get_icon(name: str, color: str = "#e8ebf1", size: int = 16) -> QIcon:
    """Render a bundled Lucide icon as a QIcon tinted with `color`."""
    return QIcon(get_pixmap(name, color, size))


ICON_SIZE = QSize(16, 16)
